import {projectInputFor,projectInputStatusHTML} from './project-input.js?v=20261113-support1';
import {courseFlowRoute,courseFlowActions,bindCourseFlowActions,renderCourseFlowSteps,createCourseFlowDrafts} from './course-flow.js?v=20261113-flow1';
import {captureCalculation,RELEASE} from './material-notebook.js?v=20261113-route1';
import {esc,num,table,notes,sources,controlsHTML,readControls,resultHTML,bindResult} from './principles-views.js?v=20261110-en1';
import {renderResponseProjects} from './response-projects.js?v=20261113-route1';
const object=x=>x&&typeof x==='object'&&!Array.isArray(x);
const options=(rows,v)=>rows.map(([id,title])=>`<option value="${esc(id)}" ${String(id)===String(v)?'selected':''}>${esc(title)}</option>`).join('');
let catalogPromise,lastResult=null;
const catalog=()=>catalogPromise??=fetch('data/principles-materials.json?v='+RELEASE).then(r=>{if(!r.ok)throw Error("The course on order parameters, magnetic exchange and conserved quantities could not be loaded");return r.json();}).catch(e=>{catalogPromise=null;throw e;});
export const getPrinciplesResult=()=>lastResult;
export const principlesCourseRoute=(id,query='')=>'#classroom/'+({order:'structure-dynamics',exchange:'spin',conservation:'continuous'}[id]||'crystal')+'?module='+id+(query?'&'+query:'');
const select=(label,key,rows,value)=>`<label>${esc(label)}<select id="pw-${key}">${options(rows,value)}</select></label>`;

export async function renderPrinciplesView({container,selection={},run,cancelRun,download,onOpenProjectLab,canOpenProjectInput,onNavigate=()=>{},onLocation=()=>{}}){
 container.innerHTML="<div class=\"obs-page qm-page response-page principles-page\"><p role=\"status\">Preparing the order-parameter, magnetic-exchange, and conservation lessons…</p></div>";
 const root=container.firstElementChild,$=s=>root.querySelector(s),current=()=>root.parentNode===container&&container.isConnected!==false;lastResult=null;
 let data;try{data=await catalog();}catch(e){if(current())root.innerHTML=`<p role="alert">${esc(e.message)}</p>`;return;}if(!current())return;
 const flowSteps=new Map(),flowDrafts=createCourseFlowDrafts();
 let module=data.modules.find(m=>m.id===selection.module)||data.modules[0],lesson=data.lessons.find(l=>l.id===selection.lesson&&l.module===module.id)||data.lessons.find(l=>l.module===module.id),exercise=data.exercises.find(e=>e.id===selection.exercise&&e.module===module.id)||data.exercises.find(e=>e.lesson===lesson.id),tab=selection.calculationOnly?'lab':selection.atlasOnly?'cases':['learn','lab','derive','cases','project'].includes(selection.tab)?selection.tab:'learn';
 if(selection.exercise)lesson=data.lessons.find(l=>l.id===exercise.lesson)||lesson;
 const defaults=Object.fromEntries(data.modules.map(m=>[m.id,Object.fromEntries(m.fields.map(f=>[f.key,f.default]))]));
 const forms=structuredClone(defaults),material=data.cases.find(c=>c.id===selection.material&&c.module===module.id);let preset=selection.preset||material?.preset||'';
 const applyPreset=id=>{const p=module.presets.find(p=>p.id===id);if(p){forms[module.id]={...structuredClone(defaults[module.id]),...structuredClone(p.input)};if(p.input.data)forms[module.id].content=JSON.stringify(p.input.data,null,2);preset=p.id;}};applyPreset(preset);
 const projectLoad=projectInputFor(selection,module.action,forms[module.id]);if(projectLoad.status==='loaded'){forms[module.id]=projectLoad.input;preset='';tab='lab';}
 let result=null,busy=false,ticket=0,progress={},prediction=null,predicted=-1,predictionTime='',predictionReport=null;try{const p=JSON.parse(localStorage.getItem('symmetry-lab.principles.progress.v1')||'{}');if(object(p))progress=p;}catch{}
 const sync=()=>onNavigate({module:module.id,tab,lesson:lesson.id,exercise:exercise.id,material:selection.material,preset});
 const context=()=>new URLSearchParams({module:module.id,...(selection.material?{material:selection.material}:{}),...(preset?{preset}:{})}).toString();
 const links=()=>`<div class="obs-links"><a data-course-flow-learn href="${esc(courseFlowRoute(principlesCourseRoute(module.id),{module:module.id,lesson:lesson.id,exercise:exercise.id,material:selection.material,preset:preset}))}">Return to this lesson →</a><a href="#atlas/principles?${esc(context())}">Material and model case →</a><a href="#atlas/projects?module=${module.id}">Cross-module project work →</a><a href="#atlas/notebook">Save material research records →</a></div>`;
 function invalidate(message="Parameters have changed, please run calculations to update the graph."){ticket++;result=null;lastResult=null;prediction=null;predicted=-1;predictionReport=null;if(busy){cancelRun?.();busy=false;}if($('#pw-status'))$('#pw-status').textContent=message;if($('#pw-result'))$('#pw-result').innerHTML=`<p role="status">${esc(message)}</p>`;if($('#pw-run'))$('#pw-run').disabled=false;}
 function draw(){if(!current())return;onLocation((selection.calculationOnly?"Computing Center / ":selection.atlasOnly?"group and material map / ":"Learning center / ")+module.title);root.innerHTML=`<header class="obs-header"><span class="obs-eyebrow">SYMMETRY · CONSTRAINTS · CONSERVATION</span><h2>${selection.atlasOnly?"Derivation of allowed terms and physical consequences from symmetry":esc(module.title)}</h2><p>${selection.atlasOnly?"Authentic material context and verifiable teaching models are interconnected.":esc(module.summary)}</p></header>${projectInputStatusHTML(projectLoad)}${selection.calculationOnly||selection.atlasOnly?'':`<nav class="obs-tabs" aria-label=" order parameter ,  magnetic exchange , and conserved quantities lesson">${[['learn',"course explanation"],['lab',"Interactive experiments"],['derive',"Guided exercises"],['cases',"Material case studies"],['project',"Project assignments"]].map(([id,t])=>`<button type="button" data-pw-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${t}</button>`).join('')}</nav>`}<div id="pw-content"></div>`;root.querySelectorAll('[data-pw-tab]').forEach(b=>b.onclick=()=>{if(!current()||![...root.querySelectorAll('[data-pw-tab]')].includes(b))return;rememberLabDraft();invalidate();tab=b.dataset.pwTab;draw();sync();});if(tab==='learn')learn();else if(tab==='derive')derive();else if(tab==='cases')cases();else if(tab==='project')renderResponseProjects({container:$('#pw-content'),selection:{project:selection.project,projectInstance:selection.projectInstance,projectStep:selection.projectStep,module:module.id},download,onOpenLab:onOpenProjectLab,canOpenCurrent:canOpenProjectInput});else {lab();flowDrafts.restore($('#pw-form'),module.id);}bindCourseFlowActions({root,prefix:'pw',isCurrent:current,onLearn:openLessonLearn,onLab:openLessonLab,labButtonId:'pw-to-lab'});}
 function learn(){$('#pw-content').innerHTML=`${select("Select theme",'lesson',data.lessons.filter(l=>l.module===module.id).map(l=>[l.id,l.title]),lesson.id)}<article class="obs-lesson"><h2>${esc(lesson.title)}</h2><p class="obs-lead">${esc(lesson.summary)}</p>${lesson.sections.map(s=>`<section><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p>${s.formula?`<div class="obs-formula">${esc(s.formula)}</div>`:''}</section>`).join('')}<div class="obs-links"><button id="pw-to-lab" class="primary">Open the corresponding experiment →</button><button id="pw-to-derive" class="secondary">step-by-step derivation →</button></div>${links()}${sources(data.sources.filter(s=>lesson.references.includes(s.id)))}</article>`;$('#pw-lesson').onchange=e=>{lesson=data.lessons.find(l=>l.id===e.target.value);exercise=data.exercises.find(e=>e.lesson===lesson.id);draw();sync();};$('#pw-to-derive').onclick=()=>{exercise=data.exercises.find(e=>e.lesson===lesson.id);tab='derive';draw();sync();};}
 function cases(){$('#pw-content').innerHTML=`<div class="obs-case-grid">${data.cases.filter(c=>selection.atlasOnly||c.module===module.id).sort((a,b)=>(b.id===selection.material)-(a.id===selection.material)).map(c=>{const m=data.modules.find(m=>m.id===c.module),q=new URLSearchParams({material:c.id,preset:c.preset}).toString();return `<article><span class="obs-eyebrow">${esc(c.kind)}</span><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p>${notes([c.assumption])}<div class="obs-links"><a href="${principlesCourseRoute(c.module,q)}">Learning and Derivation →</a><a href="#compute/${m.route}?${q}">Open the corresponding calculation →</a>${c.links.filter(([,url])=>url!=='#atlas/notebook').map(([title,url])=>`<a href="${esc(url)}">${esc(title)} →</a>`).join('')}<a href="#atlas/notebook">Research Record →</a></div></article>`;}).join('')}</div>`;}
 function rememberLabDraft(){if(tab==='lab'){let draftError='';try{forms[module.id]=readControls(module.id,root,forms[module.id]);}catch(error){draftError=error?.message||"Check the current input";}flowDrafts.remember($('#pw-form'),module.id,draftError);}}
 function openLessonLearn(){if(!current())return;rememberLabDraft();invalidate();tab='learn';draw();sync();}
 function openLessonLab(){if(!current())return;if(!module.presets.some(p=>p.id===lesson.preset))throw Error("This lesson's preset is temporarily unavailable. Return to the course directory to check it.");flowDrafts.discard(module.id);applyPreset(lesson.preset);invalidate();tab='lab';draw();sync();}
 function derive(){const list=data.exercises.filter(e=>e.module===module.id);$('#pw-content').innerHTML=`${select("Select step-by-step exercises",'exercise',list.map(e=>[e.id,(progress[e.id]?'✓ ':'')+e.title]),exercise.id)}<article class="obs-lesson"><h2>${esc(exercise.title)}</h2><p>${esc(exercise.prompt)}</p><div id="pw-steps"></div><p id="pw-progress" role="status"></p>${courseFlowActions('pw')}${links()}</article>`;const exerciseSelect=$('#pw-exercise');exerciseSelect.onchange=e=>{if(!current()||$('#pw-exercise')!==exerciseSelect)return;exercise=list.find(x=>x.id===e.target.value);lesson=data.lessons.find(l=>l.id===exercise.lesson);draw();sync();};

 const stepRoot=$('#pw-steps'),exerciseId=exercise.id;
 renderCourseFlowSteps({container:stepRoot,exercise,prefix:'pw',answerAttribute:'data-pw-answer',choicesClass:'mr-choices',completedSteps:flowSteps.get(exerciseId)||0,isCurrent:()=>current()&&$('#pw-steps')===stepRoot&&exercise.id===exerciseId,onStep:count=>flowSteps.set(exerciseId,count),onComplete:()=>{progress[exerciseId]=true;try{localStorage.setItem('symmetry-lab.principles.progress.v1',JSON.stringify(progress));}catch{}$('#pw-progress').textContent="✓ Derivation completed. Please go to the experiment to change the parameters and test this conclusion.";}});
 }

 function lab(){
  $('#pw-content').innerHTML=`<section id="br-prediction-panel" class="br-predict"></section><div class="qm-lab"><form id="pw-form" class="obs-controls">${select("teaching default",'preset',[['',"Custom/current parameters"],...module.presets.map(p=>[p.id,p.title])],preset)}${controlsHTML(module,forms[module.id])}<button id="pw-run" type="submit" class="primary">Calculate and update the demo</button><button id="pw-cancel" type="button" class="secondary">Cancel calculation</button><p id="pw-status" role="status">Python runs locally in the browser.</p></form><section id="pw-result" class="qm-results" aria-live="polite"><div class="qm-welcome"><h3>Start with a preset</h3><p>Adjust parameters, compare physical response and numerical verification, and then include the results in project work.</p></div></section></div>${links()}`;
  const panel=$('#br-prediction-panel');
  renderPrediction(panel);
  const form=$('#pw-form');form.onsubmit=e=>{e.preventDefault();calculate();};
  form.oninput=e=>{if(e.target.id==='pw-preset')return;invalidate();
   prediction=null;predicted=-1;predictionReport=null;renderPrediction(panel);try{forms[module.id]=readControls(module,root,forms[module.id]);}catch{}root.querySelectorAll('[data-pr-control]').forEach(slider=>slider.value=root.querySelector('#pw-'+slider.dataset.prControl).value);preset='';$('#pw-preset').value='';if(e.target.id==='pw-experiment')draw();
  };
  $('#pw-preset').onchange=e=>{invalidate();prediction=null;predicted=-1;predictionReport=null;applyPreset(e.target.value);draw();sync();};
  $('#pw-cancel').onclick=()=>{invalidate("The calculation has been cancelled. You can modify the parameters and rerun it.");renderPrediction(panel);$('#pw-status').textContent="Canceled";};
  root.querySelectorAll('[data-pr-control]').forEach(slider=>slider.oninput=()=>{const input=root.querySelector('#pw-'+slider.dataset.prControl);input.value=slider.value;form.oninput({target:input});});
  if(result)renderResult();
 }
 function renderPrediction(panel){
  panel.innerHTML=`<h3>Predict first, then calculate and verify</h3><p>Select a controlled preset, submit the judgment and run the calculation. Ordinary experiments can be run directly; modifying parameters will exit the current prediction question.</p><label>prediction question<select id="br-prediction-select"><option value="">Normal exploration</option>${(module.predictions||[]).map(p=>`<option value="${esc(p.id)}" ${prediction?.id===p.id?'selected':''}>${esc(p.question)}</option>`).join('')}</select></label>${prediction?`<p>${esc(prediction.question)}</p><div>${prediction.choices.map((c,i)=>`<button class="secondary" type="button" data-br-predict="${i}" data-selected="${predicted===i}" ${predictionReport?'disabled':''}>${esc(c)}</button>`).join('')}</div><p id="br-prediction-feedback" role="status">${predictionReport?esc((predictionReport.correct?"prediction is consistent with the conclusion.":"This forecast needs to be revised.")+prediction.explanation):predicted>=0?"prediction recorded. Click Calculate now to verify with real results.":"Select your prediction first, the answer will be displayed after the calculation is completed."}</p>${predictionReport?table(["Evidence for this calculation","Value"],result.summary.map(s=>[s.label,(typeof s.value==='number'?num(s.value):String(s.value??'—'))+(s.unit?' '+s.unit:'')])):''}`:''}`;
  $('#br-prediction-select').onchange=e=>{invalidate();prediction=(module.predictions||[]).find(p=>p.id===e.target.value)||null;predicted=-1;predictionReport=null;if(prediction)applyPreset(prediction.preset);draw();sync();};
  panel.querySelectorAll('[data-br-predict]').forEach(b=>b.onclick=()=>{if(predictionReport)return;predicted=Number(b.dataset.brPredict);predictionTime=new Date().toISOString();renderPrediction(panel);});
  if($('#pw-run'))$('#pw-run').disabled=busy||!!prediction&&predicted<0;
 }
 async function calculate(){if(busy)return;if(prediction&&predicted<0){$('#pw-status').textContent="Please record the prediction before running verification.";return;}let input;
  try{input=structuredClone(readControls(module,root,forms[module.id]));forms[module.id]=structuredClone(input);}catch(e){$('#pw-result').textContent=e.message;return;}
  const id=++ticket;busy=true;result=null;lastResult=null;$('#pw-run').disabled=true;$('#pw-status').textContent="is calculating...";$('#pw-result').innerHTML="<p role=\"status\">Running Python and checking numerical results...</p>";
  try{const output=await run(module.action,input);if(!current()||id!==ticket||tab!=='lab')return;result=output;
   if(prediction){predictionReport={id:prediction.id,question:prediction.question,choice:prediction.choices[predicted],correct:predicted===prediction.answer,predictedAt:predictionTime,verifiedAt:new Date().toISOString(),explanation:prediction.explanation};output.learningEvidence=structuredClone(predictionReport);try{const saved=JSON.parse(localStorage.getItem('symmetry-lab.principles.predictions.v1')||'{}');if(object(saved)){saved[prediction.id]=predictionReport;localStorage.setItem('symmetry-lab.principles.predictions.v1',JSON.stringify(saved));}}catch{}}
   lastResult={module:module.id,input:structuredClone(input),result:output};
   const route=selection.calculationOnly?'compute/'+module.route+(context()?'?'+context():''):principlesCourseRoute(module.id).slice(1);captureCalculation(module.action,input,output,{route,title:module.title,material:selection.material||''});
   $('#pw-status').textContent="Calculation complete · Export or add to a project";renderResult();const panel=$('#br-prediction-panel');if(panel)renderPrediction(panel);
  }catch(e){if(current()&&id===ticket){$('#pw-result').textContent=e.message;$('#pw-status').textContent="The calculation is not completed, please check the parameters";}}
  finally{if(current()&&id===ticket){busy=false;if($('#pw-run'))$('#pw-run').disabled=false;}}
 }
 function renderResult(){$('#pw-result').innerHTML=`<div class="qm-result-heading"><span class="tag">Browser Python Results</span><button id="pw-export" type="button" class="secondary">export complete JSON</button></div>${resultHTML(module.id,result)}<a href="#atlas/projects?module=${module.id}">includes calculations into cross-module projects →</a>`;bindResult(module.id,result,root);$('#pw-export').onclick=()=>download?.(JSON.stringify(lastResult,null,2),module.id+'-result.json','application/json');}
 draw();
}
